using NetArchTest.Rules;

namespace PaymentAuthorization.ArchitectureTest;

/// <summary>
/// Guards the Domain -> Application -> Infrastructure layering so that a technical
/// detail (framework types, I/O, HTTP, file system, etc.) can never be reached from
/// the business-rule layers by accident.
/// </summary>
public sealed class LayeringTests
{
    private const string DomainNamespace = "PaymentAuthorization.Domain";
    private const string ApplicationNamespace = "PaymentAuthorization.Application";
    private const string InfrastructureNamespace = "PaymentAuthorization.Infrastructure";

    [Fact]
    public void Domain_does_not_depend_on_application_or_infrastructure()
    {
        var result = Types.InCurrentDomain()
            .That()
            .ResideInNamespace(DomainNamespace)
            .ShouldNot()
            .HaveDependencyOnAny(ApplicationNamespace, InfrastructureNamespace)
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
    {
        var result = Types.InCurrentDomain()
            .That()
            .ResideInNamespace(ApplicationNamespace)
            .ShouldNot()
            .HaveDependencyOn(InfrastructureNamespace)
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_does_not_depend_on_framework_technical_details()
    {
        var result = Types.InCurrentDomain()
            .That()
            .ResideInNamespace(ApplicationNamespace)
            .ShouldNot()
            .HaveDependencyOnAny(
                "System.Net.Http",
                "System.IO",
                "System.Data",
                "Microsoft.EntityFrameworkCore")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    private static string Describe(TestResult result) =>
        result.FailingTypes is null
            ? "Layering rule violated."
            : "Layering rule violated by: " + string.Join(", ", result.FailingTypes.Select(t => t.FullName));
}
